846	        // (4-6) gate+skip bwd (elementwise). y_gated = y_skip*silu(z);
847	        //   y_skip = y_scan + x_main*D. sz=silu(z); dy_skip = dy_gated*sz;
848	        //   dsz = dy_gated*y_skip; dz = dsz*silu'(z); dy_scan = dy_skip;
849	        //   dx_main(D-path) = dy_skip*D; dD += Σ dy_skip*x_main.
850	        //   Buffers: dz → sc.work_di2 (dr consumed; reuse, d_inner-wide); dy_scan →
851	        //   act.y_scan (in place); dx_main accumulator(D-path) → sc.work_di
852	        //   (dy_gated consumed). dD → partial (owner channel c).
853	        for (int c = threadIdx.x; c < mb::kDInner; c += blockDim.x) {
854	            float dDc = 0.0f;
855	            #pragma unroll
856	            for (int si = 0; si < nsamp; ++si) {
857	                MambaSampleSmem::LayerAct* a = &sc.act[li][si];
858	                #pragma unroll
859	                for (int t = 0; t < mb::kSeq; ++t) {
860	                    const int r = si * mb::kSeq + t;
861	                    float sz = mb_silu(a->z[t][c]);
862	                    float xm = sc.xmain[(int64_t)r * mb::kDInner + c];
863	                    float yskip = a->y_scan[t][c] + xm * L.D[c];
864	                    float dyg = sc.work_di[(int64_t)r * mb::kDInner + c];   // dy_gated
865	                    float dyskip = dyg * sz;
866	                    float dsz = dyg * yskip;
867	                    sc.work_di2[(int64_t)r * mb::kDInner + c] = dsz * mb_silu_grad(a->z[t][c]);  // dz
868	                    dDc += dyskip * xm;
869	                    a->y_scan[t][c] = dyskip;                               // dy_scan (in place)
870	                    sc.work_di[(int64_t)r * mb::kDInner + c] = dyskip * L.D[c];  // dx_main_D (overwrite dy_gated)
871	                }
872	            }
873	            part.D[li][c] += dDc;
874	        }
875	        __syncthreads();
876	        // (7) selective scan bwd (per-sample scalar). x_main = sc.xmain (untouched).
877	        //   dy_scan = act.y_scan. Outputs: dx_main_scan → act.z (in place; z fwd
878	        //   consumed as dz=work_di2); ddt_pre → act.dt_pre (in place); dB/dC →
879	        //   smem dBmat_s/dCmat_s (zeroed per sample), consumed into sc.dbc; dA_log
880	        //   → partial. Then dx_main = D-path(work_di) + scan-path(act.z) → work_di.
881	        for (int si = 0; si < nsamp; ++si) {
882	            MambaSampleSmem::LayerAct* a = &sc.act[li][si];
883	            const int r0 = si * mb::kSeq;
884	            for (int idx = threadIdx.x; idx < mb::kSeq * mb::kState; idx += blockDim.x) {
885	                dBmat_s[idx] = 0.0f; dCmat_s[idx] = 0.0f;
886	            }
887	            __syncthreads();
888	#if !SG_MBTC_BYPASS_SCAN
889	            mb_scan_bwd(L.A_log, sc.xmain + (int64_t)r0 * mb::kDInner, a, &a->y_scan[0][0],
890	                        &a->z[0][0],        // dx_main_scan SET → act.z
891	                        &a->dt_pre[0][0],   // ddt_pre SET → act.dt_pre (in place, safe per channel)
892	                        dBmat_s, dCmat_s, part.A_log[li], red);
893	#else
894	            for (int idx = threadIdx.x; idx < mb::kSeq * mb::kDInner; idx += blockDim.x) {
895	                const int t = idx / mb::kDInner, c = idx % mb::kDInner;
896	                a->z[t][c] = 0.0f; a->dt_pre[t][c] = 0.0f;   // bypass: zero scan-bwd outputs
897	            }
898	            __syncthreads();
899	#endif
900	            // ddt_pre → dY_ddtpre acts (bf16, dt_proj dW operand) + assemble dx_dbc's
901	            //   B/C halves into sc.dbc (ddt_raw filled after dt_proj dX). dt_raw also
902	            //   needed for dt_proj dW (X operand) — already stored bf16 in acts.X_dtraw.
903	            for (int idx = threadIdx.x; idx < mb::kSeq * mb::kDInner; idx += blockDim.x) {
904	                const int t = idx / mb::kDInner, o = idx % mb::kDInner;
905	                acts.dY_ddtpre[li][(int64_t)(g0 + r0 + t) * mb::kDInner + o] = __float2bfloat16(a->dt_pre[t][o]);
906	            }
907	            // dB/dC → sc.dbc[:, dt_rank..] for this sample's rows.
908	            for (int idx = threadIdx.x; idx < mb::kSeq * mb::kState; idx += blockDim.x) {
909	                const int t = idx / mb::kState, k = idx % mb::kState;
910	                const int r = r0 + t;
911	                sc.dbc[(int64_t)r * mb::kDbc + mb::kDtRank + k] = dBmat_s[t * mb::kState + k];
912	                sc.dbc[(int64_t)r * mb::kDbc + mb::kDtRank + mb::kState + k] = dCmat_s[t * mb::kState + k];
913	            }
914	            __syncthreads();
915	        }
916	        // dx_main = D-path (work_di) + scan-path (act.z) → work_di2 (dz consumed:
917	        //   dz was needed for the in_proj dxz — STILL NEEDED at step 12! So do NOT
918	        //   clobber work_di2 yet. Put dx_main into work_di in place: work_di holds
919	        //   dx_main_D; add scan-path act.z).
920	        for (int idx = threadIdx.x; idx < nrows * mb::kDInner; idx += blockDim.x) {
921	            const int si = idx / (mb::kSeq * mb::kDInner);
922	            const int rem = idx % (mb::kSeq * mb::kDInner);
923	            const int t = rem / mb::kDInner, c = rem % mb::kDInner;
924	            sc.work_di[idx] += sc.act[li][si].z[t][c];   // dx_main = D-path + scan-path (in work_di)
925	        }
926	        __syncthreads();
927	        // (8) dt_proj dX: ddt_raw = ddt_pre @ dt_proj_w (N=dt_rank=8, K=d_inner).
928	        //   fp32 → sc.dbc[:, :dt_rank] (the ddt_raw half of dx_dbc). dt_proj dW
929	        //   (ddt_pre^T@dt_raw) + bias (Σ ddt_pre) are P2 (both operands in acts).
930	        {
931	            auto srcA = [&] (int m, int k) -> __nv_bfloat16 {
932	                return k < mb::kDInner ? acts.dY_ddtpre[li][(int64_t)(g0 + m) * mb::kDInner + k] : __float2bfloat16(0.f); };
933	            auto srcB = [&] (int n, int k) -> __nv_bfloat16 {
934	                return (n < mb::kDtRank && k < mb::kDInner) ? __float2bfloat16(L.dt_proj_w[(int64_t)k * mb::kDtRank + n]) : __float2bfloat16(0.f); };
935	            auto out = [&] (int m, int n, float v) {
936	                if (n < mb::kDtRank) sc.dbc[(int64_t)m * mb::kDbc + n] = v; };   // ddt_raw → dbc[:, :dt_rank]
937	            tc_gemm_block_unpipelined<SG_TUNED_TILE_N, /*MaxAtomsM=*/kAtomsM>(
938	                0, kAtomsM, mb::kDtRank, kceil16(mb::kDInner), srcA, srcB, out, sA, sB);
939	        }
940	        __syncthreads();
941	        // dx_dbc = cat[ddt_raw, dB, dC] now complete in sc.dbc. → dY_dxdbc acts (bf16,
942	        //   x_proj dW operand). x_proj dW (dx_dbc^T@x_main) is P2 (both in acts).
943	        for (int idx = threadIdx.x; idx < nrows * mb::kDbc; idx += blockDim.x) {
944	            const int r = idx / mb::kDbc, o = idx % mb::kDbc;
945	            acts.dY_dxdbc[li][(int64_t)(g0 + r) * mb::kDbc + o] = __float2bfloat16(sc.dbc[(int64_t)r * mb::kDbc + o]);
946	        }
947	        __syncthreads();
948	        // (9) x_proj dX: dx_main(x_proj path) = dx_dbc @ x_proj_w (N=d_inner, K=dbc=40
949	        //   PADDED→48). fp32 → sc.work_di2? No — work_di2 holds dz (needed step 12).
950	        //   Use sc.xmain (x_main fwd consumed: scan bwd done, gate bwd done, dD done —
951	        //   x_main no longer needed). dx_main(x_proj) → sc.xmain; then ADD to the
952	        //   dx_main accumulator (work_di).
953	        mbtc_gemm_dx_f32<SG_TUNED_TILE_N>(acts.dY_dxdbc[li] + (int64_t)g0 * mb::kDbc, L.x_proj_w,
954	                                          sc.xmain, mb::kDInner, mb::kDbc, sA, sB);  // dx_main_xproj
955	        __syncthreads();
956	        for (int idx = threadIdx.x; idx < nrows * mb::kDInner; idx += blockDim.x)
957	            sc.work_di[idx] += sc.xmain[idx];   // dx_main complete (work_di)
958	        __syncthreads();
959	        // (10-11) dconv = dx_main * silu'(conv) → sc.xmain (x_main consumed). conv bwd
960	        //   (per-sample scalar): conv_w/conv_b → partial; dx_main_raw → sc.work_di
961	        //   (dx_main consumed; reuse, d_inner-wide).
962	        for (int idx = threadIdx.x; idx < nrows * mb::kDInner; idx += blockDim.x) {
963	            const int si = idx / (mb::kSeq * mb::kDInner);
964	            const int rem = idx % (mb::kSeq * mb::kDInner);
965	            const int t = rem / mb::kDInner, c = rem % mb::kDInner;
966	            sc.xmain[idx] = sc.work_di[idx] * mb_silu_grad(sc.act[li][si].conv[t][c]);   // dconv
967	        }
968	        __syncthreads();
969	        for (int si = 0; si < nsamp; ++si) {
970	            MambaSampleSmem::LayerAct* a = &sc.act[li][si];
971	            const int r0 = si * mb::kSeq;
972	            mb_conv1d_bwd(sc.xmain + (int64_t)r0 * mb::kDInner, &a->x_main_raw[0][0], L.conv_w,
973	                          part.conv_w[li], part.conv_b[li], sc.work_di + (int64_t)r0 * mb::kDInner);  // dx_main_raw
974	        }
975	        // (12) dxz = cat[dx_main_raw (work_di), dz (work_di2)] → dY_dxz acts (bf16,
976	        //   in_proj dW operand, [T, 2*d_inner]). in_proj dW (dxz^T@layer_in) is P2.
977	        for (int idx = threadIdx.x; idx < nrows * mb::kDInner; idx += blockDim.x) {
978	            const int r = idx / mb::kDInner, c = idx % mb::kDInner;
979	            acts.dY_dxz[li][(int64_t)(g0 + r) * 2 * mb::kDInner + c] = __float2bfloat16(sc.work_di[idx]);              // dx_main_raw half
980	            acts.dY_dxz[li][(int64_t)(g0 + r) * 2 * mb::kDInner + mb::kDInner + c] = __float2bfloat16(sc.work_di2[idx]); // dz half
981	        }
982	        __syncthreads();
983	        // (13) in_proj dX: dx_inproj = dxz @ in_w (N=d, K=2*d_inner). fp32 → sc.work_di
984	        //   (dx_main_raw consumed). dh = dx_inproj + dx_residual(sc.work_d) → sc.work_d
985	        //   (the previous layer's output adjoint, or the embedding grad for li=0).
986	        mbtc_gemm_dx_f32<SG_TUNED_TILE_N>(acts.dY_dxz[li] + (int64_t)g0 * 2 * mb::kDInner, L.in_w,
987	                                          sc.work_di, mb::kD, 2 * mb::kDInner, sA, sB);  // dx_inproj [nrows,d]
988	        __syncthreads();
989	        for (int idx = threadIdx.x; idx < nrows * mb::kD; idx += blockDim.x)
990	            sc.work_d[idx] += sc.work_di[idx];   // dh = residual + in_proj path
991	        __syncthreads();
992	    }
993	
994	    // ── embedding bwd: dh = grad wrt h0 [nrows,d] (sc.work_d). → dh0 acts (bf16);
995	    //    tok/pos owner-scan (P2) reads dh0. ──
996	    for (int idx = threadIdx.x; idx < nrows * mb::kD; idx += blockDim.x)
997	        acts.dh0[(int64_t)g0 * mb::kD + idx] = __float2bfloat16(sc.work_d[idx]);
998	    __syncthreads();
999	}
