1001	// ════════════════════════════════════════════════════════════════════════
1002	//  P2 — OUTPUT-STATIONARY dW (the 4 projections × kLayers = 8 weight matrices,
1003	//  dW = dYᵀ @ X, K=T). Each split into 64×N output tiles; tile_id % nCTA owns
1004	//  each, contracting the FULL T (ascending-t, no atomics, no partials) via the
1005	//  validated dW orientation (both operands transposed-staged, MaxAtomsM=1).
1006	//  Writes into `grad`. The ONLY GEMM bias is dt_proj.bias = Σ_T ddt_pre.
1007	//
1008	//  The 8 weights, in named_parameters() tensor-index order:
1009	//    L0: in_w=4, x_proj_w=7, dt_proj_w=8, out_w=10
1010	//    L1: in_w=15, x_proj_w=18, dt_proj_w=19, out_w=21
1011	//  with (dY, X) acts and Nout/Kin per the forward projection.
1012	// ════════════════════════════════════════════════════════════════════════
1013	// (still in namespace mbtc — opened above)
1014	
1015	struct MbDwSpec {
1016	    const __nv_bfloat16* dY;   // [T, Nout]
1017	    const __nv_bfloat16* X;    // [T, Kin]
1018	    int Nout; int Kin; int T;
1019	    int grad_off;
1020	    bool has_bias;             // only dt_proj
1021	    const __nv_bfloat16* dY_bias;
1022	    int bias_off;
1023	};
1024	
1025	// Build the 8 specs (cheap; all CTAs). T = B*kSeq.
1026	__device__ __forceinline__ void mbtc_build_dw_specs(
1027	        const MbActs& acts, int T, MbDwSpec spec[8]) {
1028	    // per-layer tensor indices (and dt bias idx). L0 base=2 (tok=0,pos=1), 11/layer.
1029	    for (int li = 0; li < mb::kLayers; ++li) {
1030	        const int base = 2 + li * 11;
1031	        const int in_w = base + 2, xp_w = base + 5, dt_w = base + 6, dt_b = base + 7, out_w = base + 8;
1032	        MbDwSpec& s_in = spec[li * 4 + 0];
1033	        s_in.dY = acts.dY_dxz[li];   s_in.X = acts.X_in[li];
1034	        s_in.Nout = 2 * mb::kDInner; s_in.Kin = mb::kD; s_in.T = T;
1035	        s_in.grad_off = kMambaOffsets[in_w]; s_in.has_bias = false;
1036	        MbDwSpec& s_xp = spec[li * 4 + 1];
1037	        s_xp.dY = acts.dY_dxdbc[li]; s_xp.X = acts.X_xmain[li];
1038	        s_xp.Nout = mb::kDbc; s_xp.Kin = mb::kDInner; s_xp.T = T;
1039	        s_xp.grad_off = kMambaOffsets[xp_w]; s_xp.has_bias = false;
1040	        MbDwSpec& s_dt = spec[li * 4 + 2];
1041	        s_dt.dY = acts.dY_ddtpre[li]; s_dt.X = acts.X_dtraw[li];
1042	        s_dt.Nout = mb::kDInner; s_dt.Kin = mb::kDtRank; s_dt.T = T;
1043	        s_dt.grad_off = kMambaOffsets[dt_w]; s_dt.has_bias = true;
1044	        s_dt.dY_bias = acts.dY_ddtpre[li]; s_dt.bias_off = kMambaOffsets[dt_b];
1045	        MbDwSpec& s_out = spec[li * 4 + 3];
1046	        s_out.dY = acts.dY_dyout[li]; s_out.X = acts.X_ygated[li];
1047	        s_out.Nout = mb::kD; s_out.Kin = mb::kDInner; s_out.T = T;
1048	        s_out.grad_off = kMambaOffsets[out_w]; s_out.has_bias = false;
1049	    }
1050	}
1051	
1052	template <int N>
1053	__device__ __forceinline__ int mbtc_dw_total_tiles(const MbDwSpec spec[8]) {
1054	    int n = 0;
1055	    for (int s = 0; s < 8; ++s)
1056	        n += ((spec[s].Nout + 63) / 64) * ((spec[s].Kin + N - 1) / N);
1057	    return n;
1058	}
1059	
1060	// Run ONE global dW tile gt (if owned): dW = dYᵀ @ X, contract K=T. Both operands
1061	// transposed-staged. K=T is a multiple of 16 (host enforces B%16==0 → T=B·8).
1062	template <int N>
1063	__device__ __forceinline__ void mbtc_dw_run_tile(
1064	        const MbDwSpec spec[8], int gt, float* __restrict__ grad,
1065	        __nv_bfloat16* sA, __nv_bfloat16* sB) {
1066	    int acc = 0, s = 0, m_atom = 0, n_tile = 0;
1067	    for (s = 0; s < 8; ++s) {
1068	        const int ma = (spec[s].Nout + 63) / 64;
1069	        const int nt = (spec[s].Kin + N - 1) / N;
1070	        if (gt < acc + ma * nt) { int loc = gt - acc; m_atom = loc / nt; n_tile = loc % nt; break; }
1071	        acc += ma * nt;
1072	    }
1073	    const MbDwSpec& sp = spec[s];
1074	    const int mbase = m_atom * 64;
1075	    const int n0 = n_tile * N;
1076	    const int n_real = (sp.Kin - n0) < N ? (sp.Kin - n0) : N;
1077	    const int k_steps = sp.T / wgs::kWgmmaAtomK;
1078	    const int Nout = sp.Nout, Kin = sp.Kin;
1079	    const __nv_bfloat16* dY = sp.dY; const __nv_bfloat16* X = sp.X;
1080	    // A[m=out, k=t] = dY[t,out] (transposed); B[n=in, k=t] = X[t,in] (transposed).
1081	    auto srcA = [&] (int m, int k) -> __nv_bfloat16 {
1082	        return m < Nout ? dY[(int64_t)k * Nout + m] : __float2bfloat16(0.f); };
1083	    auto srcB = [&] (int n, int k) -> __nv_bfloat16 {
1084	        int nn = n0 + n; return nn < Kin ? X[(int64_t)k * Kin + nn] : __float2bfloat16(0.f); };
1085	    auto out  = [&] (int m, int n, float v) {
1086	        if (m < Nout) grad[sp.grad_off + (int64_t)m * Kin + n0 + n] = v; };
1087	    tc_gemm_block_unpipelined<N, /*MaxAtomsM=*/1>(
1088	        mbase, /*m_atoms=*/1, n_real, k_steps, srcA, srcB, out, sA, sB);
1089	}
