1091	// ════════════════════════════════════════════════════════════════════════
1092	//  SPLIT-K dW (the "multi-CTA tiling" fix for the ~73% idle SMs in P2). The 8
1093	//  projection dW = dYᵀ@X contract K=T (=B·kSeq, 131072 at B=16384) but yield
1094	//  only ~36 output tiles → with 132 SMs, ~96 idle for ALL of P2 (PROFILED: the
1095	//  K-loop is occupancy-bound, NOT latency-bound — a K-loop double-buffer moved
1096	//  the dW phase 0%). Split-K turns each output tile into G work items (one per
1097	//  K-chunk), so the work-steal fans (n_dw·G) items over the grid → the idle SMs
1098	//  do real work. Each CTA computes a PARTIAL over its K-chunk into a per-
1099	//  (tile,chunk) scratch slot; a grid barrier; then a DETERMINISTIC ascending-
1100	//  chunk reduce sums the G partials into grad — no float atomics, fixed order,
1101	//  so A/A/A bit-determinism + the 0.08 parity hold (each partial is the SAME
1102	//  ascending-k fp32 wgmma accumulate; Σ_chunk partial == the full-K sum
1103	//  reassociated into G fp32 blocks; the tol absorbs the reassociation). G==1
1104	//  routes to the single-CTA mbtc_dw_run_tile above (no scratch, byte-identical).
1105	//
1106	//  Partial scratch layout (flat, host-sized): slot (gt, kc) at
1107	//    dw_part[((int64_t)gt*G + kc) * (64*kMbMaxTileN) + row*kMbMaxTileN + col].
1108	//  The reduce reads [0,Nrow)×[0,n_real) and scatters to grad[grad_off +
1109	//  (mbase+row)*Kin + n0+col]. Biases (dt_proj only) stay in mbtc_dw_biases.
1110	// ════════════════════════════════════════════════════════════════════════
1111	constexpr int kMbMaxTileN = SG_TUNED_TILE_N;                      // widest dW N-tile
1112	constexpr int kMbDwTileFloats = wgs::kWgmmaAtomM * kMbMaxTileN;   // 64*N per (gt,kc) slot
1113	
1114	// COMPILE-TIME max #dW output tiles (the 8 projection dW have fixed Nout/Kin —
1115	// mamba dims are compile-time — so n_dw is a constant; mbtc_dw_total_tiles
1116	// returns this at runtime, but the host needs it to size the split-K scratch).
1117	//   per layer: in(512×128), x_proj(40×256), dt_proj(256×8), out(128×256), N=kMbMaxTileN
1118	constexpr int kMbDwTilesPerLayer =
1119	      ((2*mb::kDInner + 63)/64) * ((mb::kD + kMbMaxTileN - 1)/kMbMaxTileN)      // in_proj
1120	    + ((mb::kDbc + 63)/64)      * ((mb::kDInner + kMbMaxTileN - 1)/kMbMaxTileN) // x_proj
1121	    + ((mb::kDInner + 63)/64)   * ((mb::kDtRank + kMbMaxTileN - 1)/kMbMaxTileN) // dt_proj
1122	    + ((mb::kD + 63)/64)        * ((mb::kDInner + kMbMaxTileN - 1)/kMbMaxTileN);// out_proj
1123	constexpr int kMbDwMaxTiles = mb::kLayers * kMbDwTilesPerLayer;
1124	
1125	// Split-K dW partial-scratch float count (host carves it from the workspace tail):
1126	// kMbDwMaxTiles tiles × G chunks × one 64×N slot each.
1127	__host__ __device__ __forceinline__ int64_t mb_dw_part_floats(int G) {
1128	    return (int64_t)kMbDwMaxTiles * G * kMbDwTileFloats;
1129	}
1130	
1131	// Decode global dW tile index gt → (spec index s, m_atom, n_tile). Shared by the
1132	// partial pass + the reduce so the (gt → tile geometry) map is single-source.
1133	template <int N>
1134	__device__ __forceinline__ void mbtc_dw_decode(
1135	        const MbDwSpec spec[8], int gt, int& s, int& m_atom, int& n_tile) {
1136	    int acc = 0;
1137	    for (s = 0; s < 8; ++s) {
1138	        const int ma = (spec[s].Nout + 63) / 64;
1139	        const int nt = (spec[s].Kin + N - 1) / N;
1140	        if (gt < acc + ma * nt) { int loc = gt - acc; m_atom = loc / nt; n_tile = loc % nt; return; }
1141	        acc += ma * nt;
1142	    }
1143	    s = 7; m_atom = 0; n_tile = 0;   // unreachable (gt < n_dw); keep defined
1144	}
1145	
1146	// PARTIAL dW for global tile gt over K-chunk kc of G → dw_part. K-chunk =
1147	// [kc*kc_steps, (kc+1)*kc_steps) in 16-wide k-atoms; the launcher chooses
1148	// G | (T/16) so chunks are equal + 16-aligned. Fresh ScaleD=0 per chunk → a
1149	// true partial. Writes the full 64×N tile contiguously into the (gt,kc) slot.
1150	template <int N>
1151	__device__ __forceinline__ void mbtc_dw_run_tile_splitk(
1152	        const MbDwSpec spec[8], int gt, int kc, int G, float* __restrict__ dw_part,
1153	        __nv_bfloat16* sA, __nv_bfloat16* sB) {
1154	    int s, m_atom, n_tile;
1155	    mbtc_dw_decode<N>(spec, gt, s, m_atom, n_tile);
1156	    const MbDwSpec& sp = spec[s];
1157	    const int mbase = m_atom * 64;
1158	    const int n0 = n_tile * N;
1159	    const int kc_steps = (sp.T / wgs::kWgmmaAtomK) / G;   // equal chunks (G | k_steps_total)
1160	    const int k0 = kc * kc_steps;
1161	    const int Nout = sp.Nout, Kin = sp.Kin;
1162	    const __nv_bfloat16* dY = sp.dY; const __nv_bfloat16* X = sp.X;
1163	    // srcA/srcB offset the K axis by k0*16 (the chunk's first token); k local to chunk.
1164	    auto srcA = [&] (int m, int k) -> __nv_bfloat16 {
1165	        return m < Nout ? dY[(int64_t)(k0 * wgs::kWgmmaAtomK + k) * Nout + m] : __float2bfloat16(0.f); };
1166	    auto srcB = [&] (int n, int k) -> __nv_bfloat16 {
1167	        int nn = n0 + n; return nn < Kin ? X[(int64_t)(k0 * wgs::kWgmmaAtomK + k) * Kin + nn] : __float2bfloat16(0.f); };
1168	    float* slot = dw_part + ((int64_t)gt * G + kc) * kMbDwTileFloats;
1169	    // The GEMM calls out(mbase+row, col, v) with GLOBAL m = mbase+row (srcA reads
1170	    // dY[m·Nout] so m MUST stay global), but the slot holds only THIS atom's 64
1171	    // LOCAL rows → index by (m - mbase). A `m < 64` guard would NEVER fire for
1172	    // m_atom>=1 (mbase>=64) → that atom's slot stays UNWRITTEN and the reduce sums
1173	    // garbage (the rel~1.0 dW bug). Local-row indexing fills every slot fully.
1174	    auto out  = [&] (int m, int n, float v) {
1175	        const int lr = m - mbase;
1176	        if (lr >= 0 && lr < 64 && n < N) slot[(int64_t)lr * N + n] = v; };
1177	    tc_gemm_block_unpipelined<N, /*MaxAtomsM=*/1>(
1178	        mbase, /*m_atoms=*/1, /*n_real=*/N, kc_steps, srcA, srcB, out, sA, sB);
1179	}
