1250	// Fill the (grad tensor index, partial-offset-in-CTA-slab, numel) for slot v.
1251	__device__ __forceinline__ void mbtc_part_slot(
1252	        int v, int& grad_idx, int64_t& part_off, int& numel) {
1253	    // per-layer order: A_log, D, conv_w, conv_b, n_w, n_b (6); head: norm_w,norm_b,out_w,out_b.
1254	    const int kLayerNumels[6] = {
1255	        mb::kDInner * mb::kState, mb::kDInner, mb::kDInner * mb::kConvK, mb::kDInner, mb::kD, mb::kD };
1256	    if (v < mb::kLayers * 6) {
