1259	        const int tidx[6] = { base + 0, base + 1, base + 3, base + 4, base + 9, base + 10 };  // A_log,D,conv_w,conv_b,n_w,n_b
1260	        grad_idx = tidx[kind];
1261	        // partial offset within a CTA slab:
1262	        int64_t off = (int64_t)li * kPartPerLayer;
1263	        for (int k = 0; k < kind; ++k) off += kLayerNumels[k];
1264	        part_off = off; numel = kLayerNumels[kind];
1265	    } else {
1266	        const int h = v - mb::kLayers * 6;   // 0..3: norm_w,norm_b,out_w,out_b
1267	        const int htidx[4] = { 2 + mb::kLayers * 11 + 0, 2 + mb::kLayers * 11 + 1,
1268	                               2 + mb::kLayers * 11 + 2, 2 + mb::kLayers * 11 + 3 };
1269	        const int hnum[4] = { mb::kD, mb::kD, mb::kPHead * mb::kD, mb::kPHead };
