1277	// Map a flat slab index e → (grad base offset, local index) by re-deriving the
1278	// segment via mbtc_part_slot (16 tensors; cheap, register-only — NO __shared__,
1279	// which would collide with the kernel's MbTcSmem staging arena). The `seg` cursor
1280	// is carried across the grid-stride loop so consecutive e only re-scan at tensor
1281	// boundaries (warp-coherent for long runs).
1282	__device__ __forceinline__ void mbtc_part_flat_map(
1283	        int64_t e, int& seg, int64_t& gdst) {
1284	    int gidx, numel; int64_t poff;
1285	    mbtc_part_slot(seg, gidx, poff, numel);
1286	    // advance forward (e is monotonically increasing within a thread's stride run);
1287	    // if e fell before the cached segment (first iter / stride wrap), reset to 0.
1288	    if (e < poff) { seg = 0; mbtc_part_slot(seg, gidx, poff, numel); }
1289	    while (e >= poff + numel) { ++seg; mbtc_part_slot(seg, gidx, poff, numel); }
1290	    gdst = kMambaOffsets[gidx] + (e - poff);
