140	// CALIBRATION HOOK (test_mamba_tc.py::test_tc_proj_dw_exact_on_own_operands):
141	// slice the kernel's OWN stored bf16 acts dY_dyout[L1] [T,d] and X_ygated[L1]
142	// [T,d_inner] from the workspace, returned as fp32 CPU tensors. The gate
143	// contracts them in fp32 ascending-t and compares to the kernel's
144	// out_proj.weight grad slice — isolating the output-stationary dW GEMM (K=T)
145	// from the operand-chain bf16 divergence. A ~1e-6 match proves the dW GEMM is
146	// bit-exact on its own operands, calibrating the per-tensor bf16 tol as headroom
147	// over a GEMM-exact floor. Reuses the cached workspace (call AFTER tc_train_step).
148	static std::vector<torch::Tensor> tc_dump_outproj_operands(torch::Tensor params, int64_t B) {
149	    TcScratch& sc = tc_scratch_for(params, (int)B, tc_effective_nctas(params, 4));
150	    const int T = (int)B * mb::kSeq;
151	    auto acts_bf16 = sc.workspace.slice(0, 0, mbtc::mb_acts_floats(T)).view(torch::kBFloat16);
152	    // walk mb_acts_bind to dY_dyout[1] and X_ygated[1].
153	    const int64_t d = mb::kD, di = mb::kDInner, dr = mb::kDtRank, dbc = mb::kDbc;
154	    const int64_t Td = (int64_t)T * d, Tdi = (int64_t)T * di, Tdr = (int64_t)T * dr,
155	                  Tdbc = (int64_t)T * dbc, T2di = (int64_t)T * 2 * di;
156	    int64_t off = 0, off_Xyg1 = -1, off_dYout1 = -1;
157	    for (int li = 0; li < mb::kLayers; ++li) {
158	        off += Td;            // X_in
159	        off += Tdi;           // X_xmain
160	        off += Tdr;           // X_dtraw
161	        if (li == 1) off_Xyg1 = off;
162	        off += Tdi;           // X_ygated
163	        off += T2di;          // dY_dxz
164	        off += Tdbc;          // dY_dxdbc
165	        off += Tdi;           // dY_ddtpre
166	        if (li == 1) off_dYout1 = off;
167	        off += Td;            // dY_dyout
168	    }
169	    auto dYout1 = acts_bf16.slice(0, off_dYout1, off_dYout1 + Td).to(torch::kFloat32).to(torch::kCPU);
170	    auto Xyg1 = acts_bf16.slice(0, off_Xyg1, off_Xyg1 + Tdi).to(torch::kFloat32).to(torch::kCPU);
171	    return {dYout1, Xyg1};   // [T*d], [T*d_inner]
172	}
