174	// scalar_train_step: the SAME (mamba × AdamW) cell run through the SCALAR default
175	// launcher (launch_fused_mamba_megakernel<AdamW>, OUTSIDE the wgmma guard — this
176	// wgmma-token TU can still call it). For the step-time gate to time scalar and TC
177	// back-to-back in one process / one contention regime → an honest scalar:TC ratio.
178	// The scalar path uses its OWN workspace (nCTA*total partials + nCTA loss + 1).
179	// NOT the shipped invocation (that is dispatch.cpp via mega_mamba_real_adamw.cu);
180	// a measurement mirror. Returns {loss, reduced grad}. NOTE: the scalar mamba
181	// kernel needs ~142KB DYNAMIC smem (its launcher does the opt-in internally).
182	static std::vector<torch::Tensor> scalar_train_step(
183	        torch::Tensor params, torch::Tensor tokens, torch::Tensor targets,
184	        torch::Tensor state, double lr, double beta1, double beta2, double eps,
185	        double weight_decay, double bc1, double bc2, int64_t step) {
186	    TORCH_CHECK(params.is_cuda() && params.scalar_type() == torch::kFloat32 && params.is_contiguous());
187	    TORCH_CHECK(params.numel() == kMambaTotalElems, "params must be the flat mamba blob (", kMambaTotalElems, ")");
188	    TORCH_CHECK(tokens.is_cuda() && tokens.scalar_type() == torch::kInt32 && tokens.is_contiguous());
189	    TORCH_CHECK(targets.is_cuda() && targets.scalar_type() == torch::kInt32 && targets.is_contiguous());
190	    const int B = (int)targets.numel();
191	    TORCH_CHECK(tokens.numel() == (int64_t)B * mb::kSeq, "tokens must be [B,kSeq]");
192	    const int64_t total = kMambaTotalElems;
193	    TORCH_CHECK(state.is_cuda() && state.scalar_type() == torch::kFloat32 && state.is_contiguous()
194	                && state.numel() >= 3 * total, "state must be contiguous fp32 [>=3*total]");
195	
196	    int dev = params.get_device();
197	    int n_sms = 1;
198	    cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
199	
200	    static torch::Tensor s_gn, s_ga, s_gg, s_ws;
201	    static int64_t s_ws_floats = 0;
202	    const int64_t need = (int64_t)n_sms * total + n_sms + 1;
203	    if (!s_gn.defined()) {
204	        auto oi = torch::dtype(torch::kInt32).device(params.device());
205	        s_gn = torch::zeros({1}, oi); s_ga = torch::zeros({1}, oi); s_gg = torch::zeros({1}, oi);
206	    }
207	    if (s_ws_floats < need) {
208	        s_ws = torch::empty({need}, torch::dtype(torch::kFloat32).device(params.device()));
209	        s_ws_floats = need;
210	    }
211	    auto grad = torch::zeros({total}, torch::dtype(torch::kFloat32).device(params.device()));
212	    float* loss_out = s_ws.data_ptr<float>() + (int64_t)n_sms * total + n_sms;
213	
214	    PersistentContext ctx{
215	        s_gn.data_ptr<int>(),
216	        reinterpret_cast<unsigned*>(s_ga.data_ptr<int>()),
217	        reinterpret_cast<unsigned*>(s_gg.data_ptr<int>()),
218	        ::sg::fused::sm90::kMambaNumTensors, 0u};
219	
220	    FusedOptState st;
221	    float* m = state.data_ptr<float>();
222	    st.exp_avg = m; st.exp_avg_sq = m + total;
223	    st.lr = (float)lr; st.beta1 = (float)beta1; st.beta2 = (float)beta2;
224	    st.eps = (float)eps; st.wd = (float)weight_decay;
225	    st.bc1 = (float)bc1; st.bc2 = (float)bc2;
226	
227	    MambaTokenCtx tok;
228	    tok.tokens = tokens.data_ptr<int>();
229	    tok.targets = targets.data_ptr<int>();
230	    tok.B = B;
231	    tok.workspace = s_ws.data_ptr<float>();
232	    tok.loss_out = loss_out;
233	
234	    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
235	    cudaError_t err = ::sg::fused::sm90::launch_fused_mamba_megakernel<OptId::AdamW>(
236	        ctx, params.data_ptr<float>(), tok, grad.data_ptr<float>(),
237	        (float)lr, (int)step, st, stream);
238	    TORCH_CHECK(err == cudaSuccess, "scalar mamba megakernel launch failed: ", cudaGetErrorString(err));
239	    C10_CUDA_CHECK(cudaStreamSynchronize(stream));
240	
241	    auto loss_cpu = s_ws.slice(0, (int64_t)n_sms * total + n_sms, (int64_t)n_sms * total + n_sms + 1)
242	                        .to(torch::kCPU);
243	    return {loss_cpu, grad};
244	}
