257	// =========================================================================
258	//  PersistentContext — the bundle of global scratch a generated L3 megakernel
259	//  needs. The host allocates these (all zero-initialized) and passes their
260	//  device pointers to the kernel. Grouping them keeps the generated kernel
261	//  signatures uniform across all 99 cells.

__device__ __forceinline__ void looksam_apply_step(
    ParamT* __restrict__ param,
    float* __restrict__ exp_avg,
    float* __restrict__ exp_avg_sq,
    const float* __restrict__ sam_dir,
    const GradT* __restrict__ grad,
    const float alpha,         // SAM blend strength
    const float lr,
    const float beta1,
    const float beta2,
    const float eps,
    const float wd,
    const float bc1,
    const float bc2,
    const int64_t idx
) {
    const float g = static_cast<float>(grad[idx]);
    const float p = static_cast<float>(param[idx]);
    const float g_adj = (1.0f - alpha) * g + alpha * sam_dir[idx];

    const float m = beta1 * exp_avg[idx]    + (1.0f - beta1) * g_adj;
    const float v = beta2 * exp_avg_sq[idx] + (1.0f - beta2) * g_adj * g_adj;
    exp_avg[idx]    = m;
    exp_avg_sq[idx] = v;

    // bc1, bc2 un-inverted (= 1 - beta^t): divide for bias correction.
    const float update = (m / sg_safe_bc(bc1)) / (sqrtf(v / sg_safe_bc(bc2)) + eps);
    param[idx] = static_cast<ParamT>(p - lr * (update + wd * p));
}

